// fc-terms-link.js -- 1st Central Digital T&Cs demo.
// Cloned from consent-form-link-url-encoded.js (consent-form demo, node 6).
// Builds the customer's review link: a fresh session_id (so the agent tree can
// read the customer's session back via Connected Object 1197) plus the
// selected terms_score and the customer name, URL-encoded so email clients
// keep the link as one clickable token.
//
// SET THIS after importing the Customer tree: its Zingtree tree id.
var CUSTOMER_TREE_ID = "CUSTOMER_TREE_ID";

function generateGuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxx'.replace(/[xy]/g, function (c) {
    let r = Math.random() * 16 | 0,
        v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

let guid = generateGuid();

let url = "https://zingtree.com/preview/" + CUSTOMER_TREE_ID
  + "?session_id=" + guid
  + "&zv_terms_score=" + encodeURIComponent(ZT.getVariableValue("terms_score", ""))
  + "&zv_policy_number=" + encodeURIComponent(ZT.getVariableValue("policy_number", ""))
  + "&zv_customer_name=" + encodeURIComponent(ZT.getVariableValue("full_name", ""));

ZT.setFormData("terms_form_link", url);
ZT.setFormData("customer_terms_session_id", guid);

