// fc-terms-dictionary.js -- 1st Central Digital T&Cs demo (cloned from the
// consent dictionary pattern, node 17 of the consent-form demo agent tree).
// Purpose: terms_score -> T&Cs text, document name, product, version.
// Mirrors termsData in node 4 of the Customer tree -- keep both in sync.
// ALL WORDING IS DEMO SAMPLE TEXT, not 1st Central's approved policy terms.
// Outputs: terms_instruction (text), document_name, product, document_version
//          (form data); transforms.terms_html (paragraph HTML).
var termsData = {
  "car_policy_terms_new_business": {
    "document": "Car Insurance Policy Booklet - Terms & Conditions",
    "product": "Comprehensive Car Insurance",
    "version": "DEMO-PB-2026.1",
    "terms": "[DEMO SAMPLE WORDING - replace with 1st Central approved text before any customer use]\n\nYour policy is a contract between you and us. It is made up of this policy booklet, your schedule, your certificate of motor insurance and your Statement of Fact. Please read them together.\n\nWe have relied on the information you gave us when you took out this policy. If any of it is incorrect or incomplete, or changes during the policy term, you must tell us. If you do not, we may change your premium, refuse a claim or cancel your policy.\n\nYour certificate of motor insurance shows who can drive your car and what it can be used for. Driving outside these limits means you will not be covered.\n\nYour policy excess is shown on your schedule. You will need to pay the excess towards any claim, in addition to any voluntary excess you chose.\n\nYou can cancel within 14 days of receiving your documents and receive a refund of the premium for the days you were not covered, less a cancellation fee of [GBP X - sample].\n\nBy confirming below you agree that you have read and understood these terms and that the information in your Statement of Fact is correct."
  },
  "car_policy_terms_renewal": {
    "document": "Car Insurance Renewal Invitation - Terms & Conditions",
    "product": "Comprehensive Car Insurance (Renewal)",
    "version": "DEMO-RN-2026.1",
    "terms": "[DEMO SAMPLE WORDING - replace with 1st Central approved text before any customer use]\n\nYour renewal invitation sets out the price and cover for your next policy year. Please check that your details, drivers, vehicle and annual mileage are still correct.\n\nSome terms may have changed since last year. Changes to your cover, excess or optional extras are highlighted in your renewal schedule.\n\nIf you have made any claims, had any convictions or changed address since your last renewal, you must tell us before your renewal date.\n\nIf you pay by Direct Debit or continuous payment authority, your policy will renew automatically unless you tell us you do not want it to.\n\nBy confirming below you agree that you have read and understood the renewal terms and that your details are correct."
  },
  "car_policy_terms_addons": {
    "document": "Car Insurance Policy Booklet + Optional Extras Terms",
    "product": "Comprehensive Car Insurance with Optional Extras",
    "version": "DEMO-PB-2026.1 / DEMO-OX-2026.1",
    "terms": "[DEMO SAMPLE WORDING - replace with 1st Central approved text before any customer use]\n\nYour policy is a contract between you and us, made up of your policy booklet, schedule, certificate of motor insurance and Statement of Fact. Please read them together.\n\nWe have relied on the information you gave us. If any of it is incorrect or changes during the policy term, you must tell us, or we may change your premium, refuse a claim or cancel your policy.\n\nYour policy excess is shown on your schedule and applies to every claim.\n\nOptional extras are separate products with their own terms. On the next screen you will be asked to confirm, for each optional extra, whether you want it and that you have read its terms.\n\nBy confirming below you agree that you have read and understood the main policy terms."
  },
  "mid_term_adjustment_terms": {
    "document": "Mid-Term Adjustment Confirmation",
    "product": "Comprehensive Car Insurance (Policy Change)",
    "version": "DEMO-MTA-2026.1",
    "terms": "[DEMO SAMPLE WORDING - replace with 1st Central approved text before any customer use]\n\nYou have asked us to change your policy. The change, the date it takes effect and any additional premium or refund are shown on your updated schedule.\n\nAn administration fee of [GBP X - sample] applies to policy changes made after the cooling-off period.\n\nYour updated certificate of motor insurance replaces any previous certificate from the date shown.\n\nAll other terms of your policy remain unchanged.\n\nBy confirming below you agree that you have read and understood the changes to your policy."
  },
  "cancellation_terms": {
    "document": "Cancellation Terms & Fees",
    "product": "Comprehensive Car Insurance (Cancellation)",
    "version": "DEMO-CX-2026.1",
    "terms": "[DEMO SAMPLE WORDING - replace with 1st Central approved text before any customer use]\n\nYou have asked us to cancel your policy. Cover will end on the date shown in your cancellation confirmation.\n\nIf you cancel outside the 14-day cooling-off period, a cancellation fee of [GBP X - sample] applies. If you have made a claim this policy year, no refund of premium will be due.\n\nIf you pay monthly, any outstanding balance owed under your credit agreement will still need to be paid.\n\nYou must not drive the vehicle after the cancellation date unless you have arranged other insurance.\n\nBy confirming below you agree that you have read and understood the cancellation terms and fees."
  }
};

function esc(s) {
  return String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// Plain text with \n\n paragraph breaks -> <p> paragraphs. The first
// paragraph is the demo-sample banner and is rendered as a warning pill.
function termsToHtml(text) {
  return String(text || "").split("\n\n").map(function (p, i) {
    if (i === 0 && p.indexOf("[DEMO SAMPLE") === 0) {
      return '<p style="background:#fff7ed;border:1px solid #fed7aa;border-radius:10px;padding:8px 12px;color:#9a3412;font-size:13px;font-weight:700;">' + esc(p) + "</p>";
    }
    return "<p>" + esc(p) + "</p>";
  }).join("");
}

var entry = termsData[ZT.getVariableValue("terms_score", "")] || {};

ZT.setFormData("terms_instruction", entry.terms || "");
ZT.setFormData("document_name", entry.document || "");
ZT.setFormData("product", entry.product || "");
ZT.setFormData("document_version", entry.version || "");
ZT.setTransformData("terms_html", termsToHtml(entry.terms));
